import { cache } from "react";

const globalStore = globalThis as typeof globalThis & {
  __notificationPreference?: { enabled: boolean };
};

function store() {
  if (!globalStore.__notificationPreference) {
    globalStore.__notificationPreference = { enabled: false };
  }
  return globalStore.__notificationPreference;
}

export const getNotificationPreference = cache(async () => {
  return store().enabled;
});

export async function toggleNotificationPreference() {
  const current = store();
  current.enabled = !current.enabled;
  return current.enabled;
}

