import { toggleNotificationPreferenceAction } from "./actions";
import { getNotificationPreference } from "@/lib/notification-preference";

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference();

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are{" "}
        <strong>{notificationsEnabled ? "on" : "off"}</strong>.
      </p>
      <form action={toggleNotificationPreferenceAction}>
        <button type="submit">
          Turn notifications {notificationsEnabled ? "off" : "on"}
        </button>
      </form>
    </main>
  );
}

